		if method != "" && method != http.MethodGet {
			continue
		}
		if strings.ContainsAny(path, "{}") || seen[path] {
			skipped++
			continue
		}
		seen[path] = true
		spec, ok := manifest[path]
		if !ok {
			continue
		}
		gets := false
		for _, m := range spec.methods {
			if m == http.MethodGet {
				gets = true
			}
		}
		if !gets {
			skipped++
			continue
		}
